  if (!s) return -1;
  if (strcasecmp(s,"on")==0 || strcasecmp(s,"yes")==0 || strcasecmp(s,"true")==0 || strcmp(s,"1")==0) return 1;
  if (strcasecmp(s,"off")==0 || strcasecmp(s,"no")==0 || strcasecmp(s,"false")==0 || strcmp(s,"0")==0) return 0;
