  fprintf(f, "   -batch               force batch I/O\n");
  fprintf(f, "   -box                 set output mode to 'box'\n");
  fprintf(f, "   -cmd COMMAND         run \"COMMAND\" before reading stdin\n");
  fprintf(f, "   -column              set output mode to 'column'\n");
  fprintf(f, "   -csv                 set output mode to 'csv'\n");
  fprintf(f, "   -deserialize         open the database using sqlite3_deserialize()\n");
