import subprocess
def r(inp):
    p = subprocess.run(["./executable",":memory:"], input=inp.encode(), stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    return p.returncode, p.stdout.decode(errors='replace'), p.stderr.decode(errors='replace')

for inp in [
    ".mode count
CREATE TABLE t(a);
INSERT INTO t VALUES(1),(2);
SELECT * FROM t;
UPDATE t SET a=3;
DELETE FROM t;
",
    ".mode off
SELECT 1;
SELECT 2;
",
    ".mode c
SELECT 1,2 UNION ALL SELECT 3,4;
",
    ".mode jatom
SELECT 1,2 UNION ALL SELECT 3,4;
",
    ".mode jobject
SELECT 1 as a, 2 as b UNION ALL SELECT 3,4;
",
    ".mode psql
SELECT 1 as a, 2 as b UNION ALL SELECT 3,4;
",
    ".mode qbox
SELECT 1 as a, 2 as b;
",
    ".mode split
SELECT 1 as a, 2 as b UNION ALL SELECT 3,4;
",
    ".mode batch
SELECT 1,2;
",
    ".mode tty
SELECT 1 as a;
",
]:
    rc,out,err = r(inp)
    print(f"INP {inp!r} => out={out!r} err={err!r}")

